/* 04:9AC2, the variants' shared part: the point (R1, R2, R3) times 16 to
   $26F6; the push at $0132/$013A/$0142 turned into the object's axes by
   the matrix at $00E4; the point crossed with it into $68/$2C/$2E and
   four times each added to the spin sums; R8, R9 pulled and return. */
static void push_at_tail(int copy)
{
    int i;

    for (i = 0; i < 4; i++) {
        gsu.r[1] = gsu_add(gsu.r[1], gsu.r[1], 0);
        gsu.r[2] = gsu_add(gsu.r[2], gsu.r[2], 0);
        gsu.r[3] = gsu_add(gsu.r[3], gsu.r[3], 0);
    }
    gsu.r[0] = gsu_sub(gsu.r[0], gsu.r[0], 0);
    gsu_stw(FX_PUSH_ROT_GAP, gsu.r[0]);
    gsu_codes(push_at_tail_code[copy], 1);
    gsu_stw(FX_PUSH_POINT, gsu.r[1]);
    gsu_codes(push_at_tail_code[copy] + 1, 1);
    gsu_stw(FX_PUSH_POINT + 2, gsu.r[2]);
    gsu_codes(push_at_tail_code[copy] + 2, 1);
    gsu_stw(FX_PUSH_POINT + 4, gsu.r[3]);
    gsu_codes(push_at_tail_code[copy] + 3, 1);
    gsu.r[1] = gsu_ldw(FX_PUSH_ROT);
    gsu_codes(push_at_tail_code[copy] + 4, 1);
    gsu.r[2] = gsu_ldw(FX_PUSH_ROT + 8);
    gsu_codes(push_at_tail_code[copy] + 5, 1);
    gsu.r[3] = gsu_ldw(FX_PUSH_ROT + 16);
    gsu_codes(push_at_tail_code[copy] + 6, 1);
    gsu_stw(FX_PUSH_ROT, gsu_codes_then(push_at_tail_code[copy] + 7, 1, fx_row(FX_MATRIX, 2, GSU_COPY(fx_row_from_push_at_tail[copy]))));
    gsu_codes(push_at_tail_code[copy] + 8, 1);
    gsu_stw(FX_PUSH_ROT + 8, gsu_codes_then(push_at_tail_code[copy] + 9, 1, fx_row(FX_MATRIX + 6, 2, GSU_COPY(fx_row_from_push_at_tail[copy]))));
    gsu_codes(push_at_tail_code[copy] + 10, 1);
    gsu_stw(FX_PUSH_ROT + 16, gsu_codes_then(push_at_tail_code[copy] + 11, 1, fx_row(FX_MATRIX + 12, 2, GSU_COPY(fx_row_from_push_at_tail[copy]))));
    gsu_codes(push_at_tail_code[copy] + 12, 1);
    gsu.r[1] = gsu_ldw(FX_PUSH_POINT);
    gsu_codes(push_at_tail_code[copy] + 13, 1);
    gsu.r[2] = gsu_ldw(FX_PUSH_POINT + 2);
    gsu_codes(push_at_tail_code[copy] + 14, 1);
    gsu.r[3] = gsu_ldw(FX_PUSH_POINT + 4);
    gsu_codes(push_at_tail_code[copy] + 15, 1);
    gsu_stw(FX_TURN_CROSS, gsu_codes_then(push_at_tail_code[copy] + 16, 1, fx_cross(gsu.r[3], FX_PUSH_ROT + 8, gsu.r[2], FX_PUSH_ROT + 16, GSU_COPY(fx_cross_from_push_at_tail[copy]))));
    gsu_codes(push_at_tail_code[copy] + 17, 1);
    gsu_stw(0x002C, gsu_codes_then(push_at_tail_code[copy] + 18, 1, fx_cross(gsu.r[1], FX_PUSH_ROT + 16, gsu.r[3], FX_PUSH_ROT, GSU_COPY(fx_cross_from_push_at_tail[copy]))));
    gsu_codes(push_at_tail_code[copy] + 19, 1);
    gsu_stw(0x002E, gsu_codes_then(push_at_tail_code[copy] + 20, 1, fx_cross(gsu.r[2], FX_PUSH_ROT, gsu.r[1], FX_PUSH_ROT + 8, GSU_COPY(fx_cross_from_push_at_tail[copy]))));
    gsu_codes(push_at_tail_code[copy] + 21, 1);
    spin_add(FX_TURN_CROSS, FX_SPIN + 2, 4, 1, GSU_COPY(spin_add_from_push_at_tail[copy]));
    gsu_codes(push_at_tail_code[copy] + 22, 1);
    spin_add(0x002E, FX_SPIN + 4, 5, 1, GSU_COPY(spin_add_from_push_at_tail[copy]));
    gsu_codes(push_at_tail_code[copy] + 23, 1);
    spin_add(0x002C, FX_SPIN, 6, 1, GSU_COPY(spin_add_from_push_at_tail[copy]));
    gsu_codes(push_at_tail_code[copy] + 24, 1);
    pull3(0, GSU_COPY(pull3_from_push_at_tail[copy]));
    gsu_codes(push_at_tail_code[copy] + 25, 2);
}

